#!/usr/bin/env python3
"""The Passport Page of a Country That Isn't There.

Draws one invented passport spread for the Republic of Kestrelia and
writes it to /output/entry.png (1024x720 PNG, well under the 1 MiB gate).

Pure standard library only: the grader runs this with no network and no
third-party packages, so the program carries its own tiny font atlas
(pre-rendered DejaVu glyphs, packed as base64+zlib below) and its own
PNG encoder (zlib). Everything on the page is drawn procedurally:
the data page with a portrait, the machine-readable zone with real
ICAO 9303 check digits, arrival/departure stamps from neighbouring
countries, a visa sticker, and the endorsement that says what kind of
place Kestrelia is.

The country: Kestrelia, a North Atlantic island republic. Capital
Ternavik. The bearer, Elena Maris Voss, born 12 MAR 1994 in Ternavik,
holds passport KST 847 291, issued 14 JUN 2023, expiring 14 JUN 2033.
Every stamp falls after the issue date and before expiry, and the
travel history runs forward in time.
"""

import base64
import json
import math
import os
import random
import struct
import sys
import zlib
from pathlib import Path

# ---------------------------------------------------------------- font data
# Glyph atlas: DejaVu Serif Bold / Sans / Sans Bold / Sans Mono, rendered
# at 30 px and packed as {style: {ascent, descent, glyphs: {ch: [advance,
# width, height, bearing_x, bearing_y_from_baseline, base64 pixels]}}}.
# Generated once, offline, by /tmp/gen_font.py; the program only decodes it.
FONT_B64 = ""

W, H = 1024, 720

# ---------------------------------------------------------------- PNG output
def write_png(path, rgb, w, h):
    """Write an RGB bytearray as a PNG (filter 0 rows, zlib level 9)."""
    raw = bytearray()
    stride = w * 3
    for y in range(h):
        raw.append(0)
        raw += rgb[y * stride:(y + 1) * stride]
    comp = zlib.compress(bytes(raw), 9)

    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        return c + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    png = b"\x89PNG\r\n\x1a\n"
    png += chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0))
    png += chunk(b"IDAT", comp)
    png += chunk(b"IEND", b"")
    Path(path).write_bytes(png)
    return len(png)

# ---------------------------------------------------------------- canvas
class Canvas:
    """An RGBA buffer with simple vector drawing helpers."""

    def __init__(self, w, h, bg=(0, 0, 0), alpha=0):
        self.w, self.h = w, h
        self.px = bytearray([bg[0], bg[1], bg[2]] * (w * h))
        self.al = bytearray([alpha]) * (w * h) if alpha else bytearray(w * h)

    def _i(self, x, y):
        return (y * self.w + x) * 3

    def set(self, x, y, rgb, a=255):
        if 0 <= x < self.w and 0 <= y < self.h:
            i = self._i(x, y)
            if a >= 255:
                self.px[i:i + 3] = bytes(rgb)
                self.al[y * self.w + x] = 255
            elif a > 0:
                old = self.al[y * self.w + x]
                na = a + old * (255 - a) // 255
                if na:
                    for k in range(3):
                        self.px[i + k] = (rgb[k] * a + self.px[i + k] * old * (255 - a) // 255) // na
                self.al[y * self.w + x] = na

    def blend(self, x, y, rgb, a):
        """Blend an opaque colour over the pixel with strength a (0..255)."""
        if 0 <= x < self.w and 0 <= y < self.h and a > 0:
            i = self._i(x, y)
            if a >= 255:
                self.px[i:i + 3] = bytes(rgb)
                self.al[y * self.w + x] = 255
            else:
                inv = 255 - a
                for k in range(3):
                    self.px[i + k] = (rgb[k] * a + self.px[i + k] * inv) // 255
                self.al[y * self.w + x] = 255

    def fill_rect(self, x0, y0, x1, y1, rgb, a=255):
        x0, y0 = max(0, x0), max(0, y0)
        x1, y1 = min(self.w, x1), min(self.h, y1)
        if x1 <= x0 or y1 <= y0:
            return
        if a >= 255:
            row = bytes(rgb) * (x1 - x0)
            for y in range(y0, y1):
                i = self._i(x0, y)
                self.px[i:i + len(row)] = row
                self.al[y * self.w + x0:y * self.w + x1] = bytes([255]) * (x1 - x0)
        else:
            for y in range(y0, y1):
                for x in range(x0, x1):
                    self.blend(x, y, rgb, a)

    def rect(self, x0, y0, x1, y1, rgb, lw=1, a=255):
        for t in range(lw):
            self.fill_rect(x0 + t, y0 + t, x1 - t, y0 + t + 1, rgb, a)
            self.fill_rect(x0 + t, y1 - t - 1, x1 - t, y1 - t, rgb, a)
            self.fill_rect(x0 + t, y0 + t, x0 + t + 1, y1 - t, rgb, a)
            self.fill_rect(x1 - t - 1, y0 + t, x1 - t, y1 - t, rgb, a)

    def hline(self, x0, x1, y, rgb, a=255):
        self.fill_rect(x0, y, x1, y + 1, rgb, a)

    def vline(self, x, y0, y1, rgb, a=255):
        self.fill_rect(x, y0, x + 1, y1, rgb, a)

    def line(self, x0, y0, x1, y1, rgb, lw=1, a=255):
        """Bresenham line; lw>1 draws parallel offsets for thickness."""
        dx, dy = abs(x1 - x0), abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        x, y = x0, y0
        half = lw // 2
        while True:
            for t in range(-half, half + 1):
                if dx >= dy:
                    self.blend(x, y + t, rgb, a)
                else:
                    self.blend(x + t, y, rgb, a)
            if x == x1 and y == y1:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x += sx
            if e2 < dx:
                err += dx
                y += sy

    def ellipse(self, cx, cy, rx, ry, rgb, a=255, fill=True, lw=1):
        if rx <= 0 or ry <= 0:
            return
        if fill:
            for y in range(cy - ry, cy + ry + 1):
                t = (y - cy) / ry
                if abs(t) > 1:
                    continue
                dx = int(rx * math.sqrt(1 - t * t))
                self.fill_rect(cx - dx, y, cx + dx + 1, y + 1, rgb, a)
        else:
            steps = max(24, int(2 * math.pi * max(rx, ry)))
            for i in range(steps + 1):
                th = 2 * math.pi * i / steps
                x = int(cx + rx * math.cos(th))
                y = int(cy + ry * math.sin(th))
                for t in range(-(lw // 2), lw // 2 + 1):
                    self.blend(x, y + t, rgb, a)

    def circle(self, cx, cy, r, rgb, a=255, lw=1):
        self.ellipse(cx, cy, r, r, rgb, a, fill=False, lw=lw)

    def polygon(self, pts, rgb, a=255):
        """Scanline fill of a simple polygon."""
        if len(pts) < 3:
            return
        ys = [p[1] for p in pts]
        for y in range(max(0, min(ys)), min(self.h, max(ys) + 1)):
            xs = []
            n = len(pts)
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if (y0 <= y < y1) or (y1 <= y < y0):
                    xs.append(x0 + (y - y0) * (x1 - x0) / (y1 - y0))
            xs.sort()
            for i in range(0, len(xs) - 1, 2):
                self.fill_rect(int(math.ceil(xs[i])), y, int(xs[i + 1]) + 1, y + 1, rgb, a)

    def blit(self, src, dx, dy, alpha=255):
        """Composite another canvas (with its own alpha) at an offset."""
        for y in range(src.h):
            ty = dy + y
            if ty < 0 or ty >= self.h:
                continue
            for x in range(src.w):
                tx = dx + x
                if tx < 0 or tx >= self.w:
                    continue
                sa = src.al[y * src.w + x]
                if sa == 0:
                    continue
                eff = sa * alpha // 255
                if eff == 0:
                    continue
                i = (y * src.w + x) * 3
                self.blend(tx, ty, tuple(src.px[i:i + 3]), eff)

    def blit_rotated(self, src, cx, cy, angle_deg, alpha=255):
        """Composite src rotated about its centre onto (cx, cy)."""
        th = math.radians(angle_deg)
        cos_t, sin_t = math.cos(th), math.sin(th)
        scx, scy = src.w / 2.0, src.h / 2.0
        rad = int(math.hypot(scx, scy)) + 2
        for ty in range(max(0, cy - rad), min(self.h, cy + rad + 1)):
            for tx in range(max(0, cx - rad), min(self.w, cx + rad + 1)):
                dx, dy = tx - cx, ty - cy
                sx = cos_t * dx + sin_t * dy + scx
                sy = -sin_t * dx + cos_t * dy + scy
                if 0 <= sx < src.w - 1 and 0 <= sy < src.h - 1:
                    x0, y0 = int(sx), int(sy)
                    fx, fy = sx - x0, sy - y0
                    a00 = src.al[y0 * src.w + x0]
                    a10 = src.al[y0 * src.w + x0 + 1]
                    a01 = src.al[(y0 + 1) * src.w + x0]
                    a11 = src.al[(y0 + 1) * src.w + x0 + 1]
                    sa = (a00 * (1 - fx) * (1 - fy) + a10 * fx * (1 - fy)
                          + a01 * (1 - fx) * fy + a11 * fx * fy)
                    if sa < 4:
                        continue
                    i00 = (y0 * src.w + x0) * 3
                    i10 = i00 + 3
                    i01 = ((y0 + 1) * src.w + x0) * 3
                    i11 = i01 + 3
                    rgb = []
                    for k in range(3):
                        v = (src.px[i00 + k] * (1 - fx) * (1 - fy)
                             + src.px[i10 + k] * fx * (1 - fy)
                             + src.px[i01 + k] * (1 - fx) * fy
                             + src.px[i11 + k] * fx * fy)
                        rgb.append(int(v))
                    self.blend(tx, ty, tuple(rgb), int(sa * alpha // 255))

# ---------------------------------------------------------------- fonts
_FONT = None

def load_font():
    global _FONT
    if _FONT is None:
        raw = zlib.decompress(base64.b64decode(FONT_B64))
        data = json.loads(raw.decode())
        for style in data.values():
            for g in style["glyphs"].values():
                g[5] = base64.b64decode(g[5])
        _FONT = data
    return _FONT

def text_width(text, style, size, tracking=0):
    font = load_font()[style]
    scale = size / 30.0
    total = 0.0
    for ch in text:
        g = font["glyphs"].get(ch)
        if g is None:
            total += 12 * scale
        else:
            total += g[0] * scale + tracking
    return total - tracking if text else 0.0

def draw_text(cv, x, y, text, style, size, rgb, align="left", tracking=0,
              alpha=255):
    """Draw text; (x, y) is the top-left of the em box for left alignment,
    or the anchor point for centre/right alignment."""
    font = load_font()[style]
    scale = size / 30.0
    w = text_width(text, style, size, tracking)
    if align == "center":
        x -= w / 2.0
    elif align == "right":
        x -= w
    cx = x
    for ch in text:
        g = font["glyphs"].get(ch)
        if g is None:
            cx += 12 * scale + tracking
            continue
        adv, gw, gh, bx, by, pix = g
        tw = max(1, int(round(gw * scale)))
        th = max(1, int(round(gh * scale)))
        gx = int(round(cx + bx * scale))
        # y is the top of the em box: glyphs sit (ascent + bearing) below it.
        gy = int(round(y + (font["ascent"] + by) * scale))
        # Bilinear resample of the glyph coverage onto the canvas.
        for oy in range(th):
            sy = (oy + 0.5) / scale - 0.5
            y0 = int(math.floor(sy))
            fy = sy - y0
            ty = gy + oy
            if ty < 0 or ty >= cv.h:
                continue
            for ox in range(tw):
                sx = (ox + 0.5) / scale - 0.5
                x0 = int(math.floor(sx))
                fx = sx - x0
                tx = gx + ox
                if tx < 0 or tx >= cv.w:
                    continue
                cov = 0.0
                for wy, wyy in ((0, y0), (1, y0 + 1)):
                    if 0 <= wyy < gh:
                        row = wyy * gw
                        for wx, wxx in ((0, x0), (1, x0 + 1)):
                            if 0 <= wxx < gw:
                                cov += pix[row + wxx] * (1 - fx if wx == 0 else fx) \
                                    * (1 - fy if wy == 0 else fy)
                if cov > 3:
                    cv.set(tx, ty, rgb, int(cov * alpha / 255.0))
        cx += adv * scale + tracking
    return w


# ---------------------------------------------------------------- MRZ (ICAO 9303)
_MRZ_VALUES = {}
for _i, _c in enumerate("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"):
    _MRZ_VALUES[_c] = _i
_MRZ_VALUES["<"] = 0

def mrz_check(text):
    total = 0
    for i, ch in enumerate(text):
        total += _MRZ_VALUES[ch] * (7, 3, 1)[i % 3]
    return str(total % 10)

def mrz_lines():
    line1 = ("P<KST" + "VOSS" + "<<" + "ELENA<MARIS").ljust(44, "<")
    doc = "KST847291"
    dob = "940312"
    exp = "330614"
    personal = "<" * 14
    body = (doc + mrz_check(doc) + "KST" + dob + mrz_check(dob) + "F"
            + exp + mrz_check(exp) + personal + mrz_check(personal))
    line2 = body + mrz_check(body)
    assert len(line1) == 44 and len(line2) == 44, (line1, line2)
    return line1, line2

# ---------------------------------------------------------------- palette
PAPER = (244, 236, 217)
PAPER_DK = (232, 221, 196)
INK = (26, 42, 74)          # dark passport blue
INK_SOFT = (74, 88, 120)
GOLD = (176, 141, 60)
TEAL = (31, 94, 96)
RUST = (163, 51, 39)
STAMP_BLUE = (43, 76, 155)
STAMP_GREEN = (46, 107, 52)
STAMP_PURPLE = (91, 58, 122)
