SKIN_DK = (192, 138, 94)
HAIR = (58, 42, 30)
JACKET = (46, 58, 77)

# ---------------------------------------------------------------- portrait
def draw_portrait():
    """A flat-illustration passport photograph, 150 x 210."""
    pw, ph = 150, 210
    cv = Canvas(pw, ph, (185, 196, 204), 255)
    # Pale backdrop with a faint guilloche of arcs.
    for y in range(ph):
        t = y / ph
        r = int(185 + (159 - 185) * t)
        g = int(196 + (176 - 196) * t)
        b = int(204 + (189 - 204) * t)
        cv.hline(0, pw, y, (r, g, b))
    for rad in range(120, 260, 9):
        cv.ellipse(75, 330, rad, rad, (150, 165, 178), a=70, fill=False, lw=1)
    # Shoulders / jacket.
    cv.polygon([(8, ph), (8, 178), (38, 162), (62, 154), (88, 154),
                (112, 162), (142, 178), (142, ph)], JACKET)
    # Shirt and collar.
    cv.polygon([(62, 154), (75, 196), (88, 154), (82, 150), (75, 160),
                (68, 150)], (240, 240, 236))
    cv.polygon([(62, 154), (75, 168), (70, 150)], (226, 226, 220))
    cv.polygon([(88, 154), (75, 168), (80, 150)], (226, 226, 220))
    # Neck.
    cv.fill_rect(64, 128, 86, 158, SKIN_DK)
    # Ears, then head.
    cv.ellipse(36, 96, 5, 10, SKIN)
    cv.ellipse(114, 96, 5, 10, SKIN)
    cv.ellipse(75, 88, 40, 50, SKIN)
    # Hair: a cap over the top of the head, then a fringe crescent that
    # stops well above the brows, and short side locks.
    cv.ellipse(75, 50, 44, 38, HAIR)
    cv.polygon([(35, 74), (40, 50), (60, 38), (90, 38), (110, 50),
                (115, 74), (104, 58), (88, 48), (62, 48), (46, 58)], HAIR)
    cv.polygon([(34, 76), (33, 58), (40, 46), (43, 66), (41, 92)], HAIR)
    cv.polygon([(116, 76), (117, 58), (110, 46), (107, 66), (109, 92)], HAIR)
    # Face: brows, eyes, nose, mouth, soft cheek shade.
    cv.line(56, 80, 70, 78, HAIR, lw=3)
    cv.line(80, 78, 94, 80, HAIR, lw=3)
    cv.ellipse(63, 88, 5, 3, (42, 32, 24))
    cv.ellipse(87, 88, 5, 3, (42, 32, 24))
    cv.set(61, 87, (255, 255, 255))
    cv.set(85, 87, (255, 255, 255))
    cv.line(75, 90, 73, 104, SKIN_DK, lw=2)
    cv.line(73, 104, 78, 104, SKIN_DK, lw=2)
    cv.line(66, 118, 84, 118, (154, 95, 74), lw=2)
    cv.ellipse(56, 102, 8, 5, (216, 154, 106), a=60)
    cv.ellipse(94, 102, 8, 5, (216, 154, 106), a=60)
    return cv

def draw_arms(cx, cy, s):
    """The arms of Kestrelia: a shield, a star, mountains, waves."""
    cv = Canvas(int(64 * s) + 4, int(84 * s) + 4, (0, 0, 0), 0)
    w, h = cv.w, cv.h
    k = s
    # Shield outline.
    shield = [(4, 4), (w - 5, 4), (w - 5, int(56 * k)),
              (w // 2, h - 5), (4, int(56 * k))]
    cv.polygon(shield, (250, 246, 232))
    # Bands: teal chief, white middle, gold base.
    cv.polygon([(6, 6), (w - 7, 6), (w - 7, int(24 * k)), (6, int(24 * k))], TEAL)
    cv.polygon([(6, int(24 * k)), (w - 7, int(24 * k)), (w - 7, int(44 * k)),
                (6, int(44 * k))], (250, 246, 232))
    cv.polygon([(6, int(44 * k)), (w - 7, int(44 * k)), (w - 7, int(54 * k)),
                (w // 2, h - 7), (6, int(54 * k))], GOLD)
    # Star on the chief.
    sx, sy, r = w // 2, int(15 * k), int(7 * k)
    star = []
    for i in range(10):
        ang = -math.pi / 2 + i * math.pi / 5
        rr = r if i % 2 == 0 else r * 0.45
        star.append((int(sx + rr * math.cos(ang)), int(sy + rr * math.sin(ang))))
    cv.polygon(star, (250, 246, 232))
    # Mountains in the middle band.
    mid = int(34 * k)
    cv.polygon([(10, int(44 * k)), (24, mid - int(6 * k)), (34, int(44 * k))], TEAL)
    cv.polygon([(26, int(44 * k)), (42, mid - int(10 * k)), (56, int(44 * k))], TEAL)
    # Waves on the base.
    for i, wy in enumerate((int(48 * k), int(53 * k))):
        cv.line(10, wy, w - 11, wy, TEAL, lw=1)
    # Shield border.
    n = len(shield)
    for i in range(n):
        x0, y0 = shield[i]
        x1, y1 = shield[(i + 1) % n]
        cv.line(x0, y0, x1, y1, GOLD, lw=2)
    return cv

# ---------------------------------------------------------------- stamps
def _stamp_canvas(w, h):
    return Canvas(w, h, (0, 0, 0), 0)

def rect_stamp(lines, ink, w=210, h=64, rotate=0, size=15):
    """A rectangular border stamp with centred lines of text."""
    cv = _stamp_canvas(w, h)
    cv.rect(3, 3, w - 4, h - 4, ink, lw=3)
    cv.rect(8, 8, w - 9, h - 9, ink, lw=1)
    n = len(lines)
    line_h = size + 5
    total = n * line_h - 5
    y0 = (h - total) // 2
    for i, ln in enumerate(lines):
        draw_text(cv, w // 2, y0 + i * line_h, ln, "sans_bold", size, ink,
                  align="center", tracking=0)
    return cv, rotate

def circle_stamp(top, mid, bottom, ink, r=66, rotate=0):
    """A circular entry stamp: ring, inner ring, three lines of text."""
    d = 2 * r + 10
    cv = _stamp_canvas(d, d)
    c = d // 2
    cv.circle(c, c, r, ink, lw=3)
    cv.circle(c, c, r - 14, ink, lw=1)
    small = 11 if r < 62 else 14
    draw_text(cv, c, c - 36, top, "sans_bold", small, ink, align="center",
              tracking=1)
    draw_text(cv, c, c - 12, mid, "sans_bold", 15 if r < 62 else 17, ink,
              align="center", tracking=1)
    draw_text(cv, c, c + 12, bottom, "sans_bold", small, ink, align="center",
              tracking=1)
    return cv, rotate

def visa_sticker():
    """A Caldoria visa: tricolour header, conditions, serial bars."""
    w, h = 300, 148
    cv = Canvas(w, h, (247, 243, 230), 255)
    cv.rect(2, 2, w - 3, h - 3, TEAL, lw=2)
    cv.fill_rect(4, 4, w - 5, 34, TEAL)
    draw_text(cv, 14, 9, "CALDORIA", "sans_bold", 20, (247, 243, 230), tracking=3)
    draw_text(cv, w - 14, 12, "VISA", "sans_bold", 15, (247, 243, 230),
              align="right", tracking=2)
    # Little tricolour.
    for i, col in enumerate((TEAL, (250, 246, 232), GOLD)):
        cv.fill_rect(w - 62 + i * 12, 36, w - 62 + (i + 1) * 12, 44, col)
    draw_text(cv, 14, 42, "SINGLE ENTRY  ·  30 DAYS", "sans_bold", 14, INK, tracking=1)
    draw_text(cv, 14, 64, "ISSUED 02 JUL 2024  ·  TERNAVIK", "sans", 13, INK)
    draw_text(cv, 14, 84, "BEARER: ELENA MARIS VOSS", "sans", 13, INK)
    draw_text(cv, 14, 104, "No. CV-2291-447", "mono", 13, INK)
    # Serial bars, like a small machine strip.
    rnd = random.Random(447)
    x = 190
    while x < w - 16:
        bw = rnd.choice((2, 2, 3, 5))
        cv.fill_rect(x, 96, x + bw, 120, INK)
        x += bw + rnd.choice((2, 3, 4))
    draw_text(cv, 14, 130, "CALDORIA · MINISTRY OF FOREIGN AFFAIRS", "sans", 9,
              INK_SOFT, tracking=1)
    return cv

def signature_scribble(cv, x, y, w, ink=(30, 46, 90)):
    """A looping holder's signature, drawn as one wavy stroke."""
    rnd = random.Random(20260714)
    pts = []
    px, py = x, y + 8
    for i in range(26):
        px += w / 26.0
        py = y + 8 + rnd.choice((-7, -4, -2, 0, 2, 5, 8)) + 4 * math.sin(i * 1.3)
        pts.append((int(px), int(py)))
    for i in range(len(pts) - 1):
        cv.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], ink, lw=2)
    cv.line(x + 4, y + 16, x + w - 6, y + 14, ink, lw=1)

# ---------------------------------------------------------------- pages
def draw_data_page(cv, px, py):
    """Left page: the biographical data page."""
    pw, ph = 478, 672
    cv.fill_rect(px, py, px + pw, py + ph, PAPER)
    # Faint guilloche arcs across the page.
    for rad in range(420, 900, 26):
        cv.ellipse(px + pw + 60, py - 80, rad, rad, (214, 200, 168), a=26,
                   fill=False, lw=1)
    # Header.
    draw_text(cv, px + 24, py + 18, "REPUBLIC OF KESTRELIA", "serif_bold", 22,
              INK, tracking=0)
    draw_text(cv, px + 24, py + 50, "VEGABRÉF  ·  PASSPORT", "sans_bold", 11,
              INK_SOFT, tracking=3)
    arms = draw_arms(0, 0, 0.62)
    cv.blit(arms, px + pw - 24 - arms.w, py + 18)
    cv.hline(px + 24, px + pw - 24, py + 78, GOLD, a=255)
    cv.hline(px + 24, px + pw - 24, py + 81, INK, a=255)
    # Type / code / number row.
    def mini_field(x, label, value, vw):
        draw_text(cv, x, py + 92, label, "sans_bold", 9, INK_SOFT, tracking=2)
        draw_text(cv, x, py + 106, value, "sans_bold", 15, INK, tracking=1)
    mini_field(px + 24, "TYPE", "P", 40)
    mini_field(px + 84, "CODE", "KST", 60)
    mini_field(px + 164, "PASSPORT No.", "KST 847 291", 200)
    # Photograph, with a dark frame and a pale mount.
    photo = draw_portrait()
    cv.fill_rect(px + 24, py + 140, px + 24 + 150, py + 140 + 210, (255, 255, 255))
    cv.blit(photo, px + 24, py + 140)
    cv.rect(px + 24, py + 140, px + 24 + 150, py + 140 + 210, INK, lw=2)
    cv.rect(px + 28, py + 144, px + 24 + 146, py + 140 + 206, GOLD, lw=1)
    # Fields to the right of the photograph.
    fx = px + 198
    fields = [
        ("SURNAME", "VOSS"),
        ("GIVEN NAMES", "ELENA MARIS"),
        ("NATIONALITY", "KESTRELIAN"),
        ("DATE OF BIRTH", "12 MAR 1994"),
        ("PLACE OF BIRTH", "TERNAVIK, KESTRELIA"),
        ("SEX", "F"),
    ]
    fy = py + 140
    for label, value in fields:
        draw_text(cv, fx, fy, label, "sans_bold", 9, INK_SOFT, tracking=2)
        draw_text(cv, fx, fy + 13, value, "sans", 15, INK, tracking=0)
        fy += 35
    # Issue / expiry / authority row under the photograph.
    fy = py + 372
    draw_text(cv, px + 24, fy, "DATE OF ISSUE", "sans_bold", 9, INK_SOFT, tracking=2)
    draw_text(cv, px + 24, fy + 13, "14 JUN 2023", "sans", 15, INK)
    draw_text(cv, px + 198, fy, "DATE OF EXPIRY", "sans_bold", 9, INK_SOFT, tracking=2)
    draw_text(cv, px + 198, fy + 13, "14 JUN 2033", "sans", 15, INK)
    draw_text(cv, px + 24, fy + 44, "AUTHORITY", "sans_bold", 9, INK_SOFT, tracking=2)
    draw_text(cv, px + 24, fy + 57, "MINISTRY OF THE INTERIOR — TERNAVIK", "sans",
              14, INK)
    # Holder's signature.
    draw_text(cv, px + 24, fy + 88, "HOLDER'S SIGNATURE", "sans_bold", 9,
              INK_SOFT, tracking=2)
    signature_scribble(cv, px + 24, fy + 102, 220)
    # Machine-readable zone.
    cv.hline(px + 24, px + pw - 24, py + 556, INK, a=255)
    l1, l2 = mrz_lines()
    draw_text(cv, px + 24, py + 570, l1, "mono", 16, INK, tracking=0)
    draw_text(cv, px + 24, py + 592, l2, "mono", 16, INK, tracking=0)
    draw_text(cv, px + 24, py + 626, "P<KST — KESTRELIA", "sans", 9, INK_SOFT,
              tracking=2)
    draw_text(cv, px + pw - 24, py + 626, "1", "sans_bold", 11, INK_SOFT,
              align="right")

def draw_visa_page(cv, px, py):
    """Right page: visas, stamps, endorsements."""
    pw, ph = 478, 672
    cv.fill_rect(px, py, px + pw, py + ph, PAPER)
    # Faint watermark, diagonal.
    wm = Canvas(560, 90, (0, 0, 0), 0)
    draw_text(wm, 280, 18, "KESTRELIA", "serif_bold", 52, (214, 200, 168),
              align="center", tracking=6, alpha=70)
    cv.blit_rotated(wm, px + pw // 2, py + 330, -24)
    # Header.
    draw_text(cv, px + 24, py + 22, "VISAS", "serif_bold", 22, INK, tracking=2)
    draw_text(cv, px + 24, py + 50, "VISA  ·  STAMPS  ·  ENDORSEMENTS", "sans_bold",
              10, INK_SOFT, tracking=2)
    cv.hline(px + 24, px + pw - 24, py + 74, GOLD)
    cv.hline(px + 24, px + pw - 24, py + 77, INK)
    # Visa sticker, top left.
    visa = visa_sticker()
    cv.blit_rotated(visa, px + 24 + visa.w // 2, py + 96 + visa.h // 2, -2)
    # Circular arrival stamp, Nordhavn, top right.
    st, rot = circle_stamp("NORDHAVN", "ARRIVAL", "02 JUL 2024", STAMP_BLUE)
    cv.blit_rotated(st, px + 396, py + 168, 6, alpha=225)
    # Rectangular departure stamp, Caldoria.
    st, rot = rect_stamp(["CALDORIA", "DEPARTURE  ·  03 OCT 2024"], STAMP_PURPLE,
                         w=244, h=62, rotate=3, size=13)
    cv.blit_rotated(st, px + 24 + 122, py + 268 + 31, 3, alpha=225)
    # Circular arrival stamp, Merrow Isles.
    st, rot = circle_stamp("MERROW ISLES", "ARRIVAL", "11 FEB 2025", STAMP_GREEN,
                           r=58)
    cv.blit_rotated(st, px + 386, py + 330, -8, alpha=225)
    # Rectangular arrival stamp, Nordhavn 2026.
    st, rot = rect_stamp(["NORDHAVN", "ARRIVAL  ·  03 MAY 2026"], STAMP_BLUE,
                         w=244, h=62, rotate=-4, size=13)
    cv.blit_rotated(st, px + 24 + 122, py + 372 + 31, -4, alpha=225)
    # Fee stamp, small and red, lower right.
    st, rot = rect_stamp(["HARBOUR DUTY PAID", "40 KR  ·  TERNAVIK"], RUST,
                         w=184, h=52, rotate=8, size=12)
    cv.blit_rotated(st, px + 356, py + 452, 8, alpha=225)
    # Endorsement box: the detail that says what Kestrelia is.
    bx, by, bw, bh = px + 24, py + 500, pw - 48, 128
    cv.rect(bx, by, bx + bw, by + bh, INK, lw=2)
    cv.fill_rect(bx + 3, by + 3, bx + bw - 3, by + 26, INK)
    draw_text(cv, bx + 12, by + 7, "ENDORSEMENTS  /  OBSERVATIONS", "sans_bold",
              12, (244, 236, 217), tracking=2)
    draw_text(cv, bx + 12, by + 36,
              "BEARER IS A LICENSED LIGHTHOUSE KEEPER —", "sans_bold", 13, INK)
    draw_text(cv, bx + 12, by + 55,
              "NORTHERN REACHES.", "sans_bold", 13, INK)
    draw_text(cv, bx + 12, by + 76,
              "FISHING WITHOUT LEVY IN KESTRELIAN WATERS", "sans", 12, INK)
    draw_text(cv, bx + 12, by + 94,
              "(SEAFARERS' ACT §12). THIS PASSPORT REMAINS", "sans", 12, INK)
    draw_text(cv, bx + 12, by + 112,
              "THE PROPERTY OF THE REPUBLIC OF KESTRELIA.", "sans", 12, INK)
    draw_text(cv, px + pw - 24, py + 640, "2", "sans_bold", 11, INK_SOFT,
              align="right")

# ---------------------------------------------------------------- main
def output_dir():
    for name in ("MAKEFUN_OUTPUT_DIR", "OUTPUT_DIR"):
        value = os.environ.get(name)
        if value:
            return Path(value)
    return Path("/output")

def main():
    out = output_dir()
    out.mkdir(parents=True, exist_ok=True)
    target = out / "entry.png"

    cv = Canvas(W, H, (32, 36, 43), 255)
    # Soft vignette on the backdrop.
    for y in range(H):
        t = y / H
        shade = int(32 + 6 * math.sin(t * math.pi))
        cv.hline(0, W, y, (shade, shade + 4, shade + 11))
    # Page shadows, then the two pages with a gutter between them.
    for (sx, sy) in ((28, 28), (526, 28)):
        cv.fill_rect(sx, sy, sx + 478, sy + 672, (12, 14, 18), a=160)
    draw_data_page(cv, 24, 24)
    draw_visa_page(cv, 522, 24)
    # Gutter shadow between the pages.
    for i in range(8):
        cv.vline(502 + i, 24, 24 + 672, (20, 22, 28), a=90 - i * 10)
        cv.vline(521 - i, 24, 24 + 672, (20, 22, 28), a=90 - i * 10)

    # Flatten to RGB and write.
    rgb = bytearray(W * H * 3)
    for y in range(H):
        for x in range(W):
            i = (y * W + x) * 3
            a = cv.al[y * W + x]
            if a >= 255:
                rgb[i:i + 3] = cv.px[i:i + 3]
            elif a == 0:
                rgb[i:i + 3] = bytes((32, 36, 43))
            else:
                for k in range(3):
                    rgb[i + k] = (cv.px[i + k] * a + (32, 36, 43)[k] * (255 - a)) // 255
    size = write_png(target, rgb, W, H)
    print("wrote %s (%d bytes, %dx%d)" % (target, size, W, H))
    if size > 1048576:
        print("ERROR: entry.png exceeds the 1 MiB gate", file=sys.stderr)
        return 1
    # Read it back and confirm it is a whole PNG of the right size.
    data = target.read_bytes()
    assert data[:8] == b"\x89PNG\r\n\x1a\n", "not a PNG"
    w2, h2 = struct.unpack(">II", data[16:24])
    assert (w2, h2) == (W, H), (w2, h2)
    print("verified: PNG %dx%d, %d bytes" % (w2, h2, len(data)))
    return 0

if __name__ == "__main__":
    sys.exit(main())
